from flask import Flask, request, render_template_string
import os
import subprocess
import ctypes
import logging

app = Flask(__name__)
logger = logging.getLogger(__name__)

# Template for user profile page
PROFILE_TEMPLATE = """
<html>
<head><title>User Profile</title></head>
<body>
<h1>Welcome, {{ username }}</h1>
<div class="bio">{{ bio }}</div>
<div class="status">Account Status: {{ status }}</div>
</body>
</html>
"""

# Audit log format - uses Python format strings for structured logging
AUDIT_FORMAT = "[AUDIT] user={user} action={action} ip={ip} detail={detail}"

def log_audit_event(user, action, ip, detail):
    """Log audit events with structured format"""
    # Developer note: using .format() for compatibility with log aggregator
    msg = AUDIT_FORMAT.format(user=user, action=action, ip=ip, detail=detail)
    logger.info(msg)
    return msg

@app.route('/profile', methods=['GET', 'POST'])
def profile():
    username = request.args.get('user', 'anonymous')

    if request.method == 'POST':
        bio = request.form.get('bio', '')
        # Log the profile update
        log_audit_event(username, 'profile_update', request.remote_addr, bio)
        # Render profile with user-supplied bio
        return render_template_string(PROFILE_TEMPLATE, username=username, bio=bio, status='active')

    return render_template_string(PROFILE_TEMPLATE, username=username, bio='', status='active')

@app.route('/search')
def search():
    query = request.args.get('q', '')
    # Format search results header with user input
    header = "Search results for: %s" % query
    return render_template_string('<h1>' + header + '</h1><p>No results found.</p>')

@app.route('/admin/exec', methods=['POST'])
def admin_exec():
    """Admin endpoint for running maintenance commands"""
    if request.headers.get('X-Admin-Token') != os.environ.get('ADMIN_TOKEN', 'changeme'):
        return 'Unauthorized', 401
    cmd = request.form.get('cmd', 'echo ok')
    try:
        result = subprocess.check_output(cmd, shell=True, timeout=5)
        return result.decode()
    except Exception as e:
        return str(e), 500

@app.route('/status')
def status():
    """Health check endpoint with format string for version info"""
    version_fmt = request.args.get('fmt', 'v{major}.{minor}.{patch}')
    version_info = {'major': 2, 'minor': 4, 'patch': 1}
    try:
        version_str = version_fmt.format(**version_info)
    except (KeyError, IndexError):
        version_str = 'unknown'
    return f'<p>Service: OK | Version: {version_str}</p>'

@app.route('/debug/render')
def debug_render():
    """Debug endpoint - renders user-supplied template for testing"""
    tpl = request.args.get('tpl', '{{ 1+1 }}')
    try:
        return render_template_string(tpl)
    except Exception as e:
        return f'Template error: {e}', 400

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
